*   **SDA:** Connect to GPIO 21
*   **SCL:** Connect to GPIO 22

**Software Setup and Code Example:**

This setup uses the I2C protocol. You will need to install the following libraries via the Arduino Library Manager:
1.  `Adafruit GFX Library`
2.  `Adafruit SSD1306`

The sketch must initialize the I2C communication and the display object.

```cpp
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// Define display size (e.g., 128x64 or 128x32)
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64 

// Define the I2C address (0x3C or 0x3D depending on the module)
#define OLED_ADDR 0x3D 

// Initialize the display object using the dimensions and address
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

void setup() {
  Serial.begin(115200);

  // Initialize I2C communication
  Wire.begin(21, 22); 

  // Initialize the display
  if(!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) { 
    Serial.println(F("SSD1306 allocation failed"));
    for(;;); // Don't proceed if initialization fails
  }

  // Display basic information
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0,0);
  display.println("ESP32 Connected!");
  display.display(); // Show the buffer content on the screen
}

void loop() {
  // Your main program logic goes here
}
```

